                /** Nastavení povolení checkboxů a jejich hodnot */
                setCheckboxes() {
                    //checkbox make (Upravit celkovou částku)
                    var make_field = this.$form.findFields("make");
                    var make_edit = true;
                    var make_val = true;
                    //u objednávky automaticky snižuju cenu
                    //347.4 08.08.03 - pokud se jedná o smlouvu s typem ceny=volná, pak taky -- a dokonce to zakážu změnit
                    //353.1 16.06.05 doplněn lim. příslib
                    //358.20 14.05.08 - vyhozeno - smlpid_p.typ_dok = ng_typdokObj or ( ( smlpid_p.typ_dok = ng_typdokSml or smlpid_p.typ_dok = ng_typdokLim ) and smlpid_p.findoc.typ_ceny = ng_typcenyVolna )
                    //376.9 07.04.16 změna podmínky - přidán i parametr 'sml_rad_dokvaly'
                    if (this.smlpid.pripad?.ktg_sml == 60 /* Interface.KategorieDokladu.ng_ktgsmlOdbObj */ || this.smlpid.pripad?.ktg_sml == 50 /* Interface.KategorieDokladu.ng_ktgsmlDodObj */ ||
                        this.smlpid.pripad?.typ_ceny == 20 /* Interface.TypCeny.ng_typcenyVolna */ || this.sml_rad_dokvaly == 1) {
                        //358.20 14.05.08 - vyhozeno smlpid_p.typ_dok = ng_typdokSml and smlpid_p.findoc.typ_ceny = ng_typcenyVolna a nahrazeno kategorií sml
                        if (this.smlpid.pripad?.typ_ceny == 20 /* Interface.TypCeny.ng_typcenyVolna */) {
                            make_edit = false;
                        }
                        //376.9 07.04.16 přidáno sem do bloku
                        if (this.eko_rad_dfken == 2 || (this.eko_rad_dfken == 1 && this.smlpid.pripad?.JeVydaj)) {
                            make_edit = false;
                        }
                    }
                    else {
                        make_val = false;
                    }
                    make_field.gfield("option", "disabled", !make_edit);
                    make_field.gfield("setInitial", make_val);
                    //checkbox make_rozpis (Upravit rozpis částky)
                    var make_rozpis_field = this.$form.findFields("make_rozpis");
                    var make_rozpis_edit = true;
                    var make_rozpis_val = true;
                    //výchozí stav je TRUE - u případu s volnou cenou to nahodím povinně a zakážu měnit
                    if (this.smlpid.pripad?.typ_ceny == 20 /* Interface.TypCeny.ng_typcenyVolna */) {
                        make_rozpis_edit = false;
                    }
                    //370.17 07.05.13 pokud je nastaven DB parametr, že pro schválení částka položek má odpovídat rozpisu, pak se rovněž přednastaví
                    //376.9 07.04.16 vyhozeno Else If - podmínka bude platit vždy
                    //386.8 10.06.21 oprava hodnoty parametru, protože 1 odpovídá tomu, že se částky mohou lišit
                    if (this.sml_rad_dokvalr == 0) {
                        //v případě PFK se neumožní změna
                        if (this.eko_rad_dfken == 2 || (this.eko_rad_dfken == 1 && this.smlpid.pripad?.JeVydaj)) {
                            make_rozpis_edit = false;
                        }
                    }
                    make_rozpis_field.gfield("option", "disabled", !make_rozpis_edit);
                    make_rozpis_field.gfield("setInitial", make_rozpis_val);
                    //checkbox make_storno_pfk (Ukončit plastnost dokladu PFK)
                    //368.23 14.02.13 řízení stornování dokladu PFK
                    //374.3 09.10.14 změna popisu - místo stornování je ukončení platnosti
                    var make_storno_pfk_field = this.$form.findFields("make_storno_pfk");
                    var make_storno_pfk_edit = true;
                    var make_storno_pfk_val = true;
                    //editace je přístupná v případě obsluhy FK
                    if (this.eko_rad_dfken > 0) {
                        //možnost volby dle parametru 'SML - ŘP Režim stornování dokladu PFK v okamžiku ukončení/uvolnění' - hodnota se přednastaví dle režimu práce
                        if (this.sml_rad_pfksto == 2) {
                            //výchozí stav je TRUE v případě obsluhy FK a dialog není volán z procesu ukončování dokladu
                            make_storno_pfk_val = (this.mode == 0) ? true : false;
                        }
                        else {
                            //platí tvrdá volba daná parametrem
                            make_storno_pfk_val = this.sml_rad_pfksto == 1;
                            //nedostupné
                            make_storno_pfk_edit = false;
                        }
                    }
                    else {
                        make_storno_pfk_val = false;
                        //nedostupné
                        make_storno_pfk_edit = false;
                    }
                    make_storno_pfk_field.gfield("option", "disabled", !make_storno_pfk_edit);
                    make_storno_pfk_field.gfield("setInitial", make_storno_pfk_val);
                }
